package com.myaaptha.domain.contacts;
import com.myaaptha.domain.privacy.UserBlockRepository;
import com.myaaptha.domain.user.UserRepository;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.security.Principal;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/people/highlights")
public class PeopleHighlightsController {
 public record Person(String key,Long memberId,Long contactId,String name,long connectedCalls,String lastCall,boolean starred,boolean hidden){}
 public record Page(boolean enabled,int days,List<Person> items,Long nextCursor){}
 public record Choice(Long memberId,Long contactId,@NotNull Boolean starred,@NotNull Boolean hidden){}
 public record Preference(boolean enabled){}
 private record Calls(long count,Instant last){}
 private final JdbcTemplate db;private final UserRepository users;private final UserBlockRepository blocks;private final AddressBookService book;
 public PeopleHighlightsController(JdbcTemplate db,UserRepository users,UserBlockRepository blocks,AddressBookService book){this.db=db;this.users=users;this.blocks=blocks;this.book=book;}
 @GetMapping public Page list(Principal principal,@RequestParam(defaultValue="frequent") String view,@RequestParam(defaultValue="0") long afterId){long owner=Long.parseLong(principal.getName());if(!Set.of("frequent","starred","hidden").contains(view)||afterId<0)throw bad("Choose a valid highlights view");boolean enabled=enabled(owner);if(view.equals("frequent")&&!enabled)return new Page(false,90,List.of(),null);var calls=calls(owner);List<Person> result=new ArrayList<>();Map<String,Map<String,Object>> flags=new HashMap<>();db.queryForList("SELECT * FROM people_highlights WHERE user_id=?",owner).forEach(r->flags.put((String)r.get("target_key"),r));Long cursor=null;
  if(view.equals("frequent")){for(var entry:calls.entrySet().stream().filter(e->e.getValue().count>=2).sorted(Comparator.<Map.Entry<Long,Calls>,Long>comparing(e->e.getValue().count).reversed().thenComparing(e->e.getValue().last,Comparator.reverseOrder()).thenComparing(Map.Entry::getKey)).toList()){var row=flags.get("m:"+entry.getKey());if(row!=null&&Boolean.TRUE.equals(row.get("hidden")))continue;var person=member(owner,entry.getKey(),entry.getValue(),row);if(person!=null)result.add(person);if(result.size()==12)break;}}
  else{String field=view.equals("starred")?"starred":"hidden";var rows=db.queryForList("SELECT * FROM people_highlights WHERE user_id=? AND id>? AND "+field+"=TRUE ORDER BY id LIMIT 51",owner,afterId);for(var row:rows.stream().limit(50).toList()){Long member=(Long)row.get("member_id"),contact=(Long)row.get("contact_id");if(member!=null){var value=member(owner,member,calls.get(member),row);if(value!=null)result.add(value);}else{var value=book.entries(owner,List.of(contact));if(!value.isEmpty())result.add(new Person("c:"+contact,null,contact,value.getFirst().displayName(),0,null,Boolean.TRUE.equals(row.get("starred")),Boolean.TRUE.equals(row.get("hidden"))));}}if(rows.size()>50)cursor=((Number)rows.get(49).get("id")).longValue();}
  return new Page(enabled,90,result,cursor);
 }
 @PostMapping @Transactional public void choose(Principal principal,@Valid @RequestBody Choice input){long owner=Long.parseLong(principal.getName());lock(owner);if((input.memberId()==null)==(input.contactId()==null))throw bad("Choose one person");String key;if(input.memberId()!=null){if(member(owner,input.memberId(),null,null)==null)throw bad("Choose an available member");if(db.queryForObject("SELECT COUNT(*) FROM people_highlights WHERE user_id=? AND member_id=?",Integer.class,owner,input.memberId())==0&&!calls(owner).containsKey(input.memberId())&&db.queryForObject("SELECT COUNT(*) FROM relationships WHERE owner_user_id=? AND related_user_id=?",Integer.class,owner,input.memberId())==0)throw bad("Choose a person from your calls or relationships");key="m:"+input.memberId();}else{if(book.entries(owner,List.of(input.contactId())).isEmpty())throw missing();key="c:"+input.contactId();}if(db.update("UPDATE people_highlights SET starred=?,hidden=? WHERE user_id=? AND target_key=?",input.starred(),input.hidden(),owner,key)==0)db.update("INSERT INTO people_highlights(user_id,target_key,member_id,contact_id,starred,hidden) VALUES(?,?,?,?,?,?)",owner,key,input.memberId(),input.contactId(),input.starred(),input.hidden());}
 @PostMapping("/preferences") @Transactional public Preference preference(Principal principal,@RequestBody Preference value){long owner=Long.parseLong(principal.getName());lock(owner);if(db.update("UPDATE people_highlight_preferences SET enabled=? WHERE user_id=?",value.enabled(),owner)==0)db.update("INSERT INTO people_highlight_preferences(user_id,enabled) VALUES(?,?)",owner,value.enabled());return value;}
 private boolean enabled(long owner){var rows=db.queryForList("SELECT enabled FROM people_highlight_preferences WHERE user_id=?",Boolean.class,owner);return rows.isEmpty()||rows.getFirst();}
 private Person member(long owner,long id,Calls calls,Map<String,Object> row){var user=users.findById(id).orElse(null);if(user==null||owner==id||!"ACTIVE".equals(user.getAccountStatus())||"MANAGED".equals(user.getIdentityType())||blocks.blockedEitherWay(owner,id))return null;String name=(Objects.requireNonNullElse(user.getFirstName(),"")+" "+Objects.requireNonNullElse(user.getSurname(),"")).trim();return new Person("m:"+id,id,null,name.isEmpty()?user.getUsername():name,calls==null?0:calls.count,calls==null?null:calls.last.toString(),row!=null&&Boolean.TRUE.equals(row.get("starred")),row!=null&&Boolean.TRUE.equals(row.get("hidden")));}
 private Map<Long,Calls> calls(long owner){Timestamp since=Timestamp.from(Instant.now().minusSeconds(90L*86400));Map<Long,Calls> result=new HashMap<>();String sql="SELECT peer,COUNT(*) AS total,MAX(at) AS latest FROM (SELECT CASE WHEN c.creator_user_id=? THEN c.target_id ELSE c.creator_user_id END AS peer,c.created_at AS at FROM communication_calls c JOIN communication_call_members a ON a.call_id=c.id AND a.user_id=? JOIN communication_call_members b ON b.call_id=c.id AND b.user_id=CASE WHEN c.creator_user_id=? THEN c.target_id ELSE c.creator_user_id END WHERE c.scope='DIRECT' AND (c.creator_user_id=? OR c.target_id=?) AND a.joined_at IS NOT NULL AND b.joined_at IS NOT NULL AND c.created_at>=? UNION ALL SELECT CASE WHEN caller_user_id=? THEN recipient_user_id ELSE caller_user_id END AS peer,created_at AS at FROM direct_calls WHERE (caller_user_id=? OR recipient_user_id=?) AND answer_sdp IS NOT NULL AND status IN ('ACCEPTED','ENDED') AND created_at>=?) x GROUP BY peer";db.query(sql,r->{result.put(r.getLong("peer"),new Calls(r.getLong("total"),r.getTimestamp("latest").toInstant()));},owner,owner,owner,owner,owner,since,owner,owner,owner,since);return result;}
 private void lock(long owner){db.queryForObject("SELECT id FROM users WHERE id=? FOR UPDATE",Long.class,owner);}
 private static ResponseStatusException bad(String s){return new ResponseStatusException(HttpStatus.BAD_REQUEST,s);}private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Person not found");}
}
